#!/usr/bin/env node/** * BANF Family Fix Agent ΓÇö v1.0 * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ * Intelligent family grouping agent that re-assigns ALL CRM members * to correct family units using co-occurrence evidence from: * *   1. Compound payment/membership names  ("Ranadhir Da/ Moumita Di") *   2. Family Universe XLSX entries       (shared compound Original Entry) *   3. Jagriti magazine comments          ("Ranadhir da's daughter") *   4. CRM communications/emails          (parent emails about children) *   5. Google Contacts                    (shared address, org) *   6. Email domain analysis              (same domain + same surname) * * Algorithm: *   ΓÇó Build a weighted graph of member-pair evidence *   ΓÇó Find connected components ΓåÆ each = one family unit *   ΓÇó Apply evidence-based familyType (individual/couple/family) *   ΓÇó Generate new FAM-2026-XXXXX IDs for each correct family * * Usage: *   node banf-family-fix-agent.js                     (dry-run, report only) *   node banf-family-fix-agent.js --fix               (apply CRM fixes) *   node banf-family-fix-agent.js --member=Ranadhir   (report for one member) *   node banf-family-fix-agent.js --verbose           (show all evidence) * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */'use strict';const XLSX   = require('xlsx');const fetch  = require('node-fetch');const fs     = require('fs');const path   = require('path');const crypto = require('crypto');// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓö