 [firstName1, lastName1, firstName2, lastName2, relationship]// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst MANUAL_OVERRIDES = [  ['Barnali',   'Mondal',      'Chiradip',   'Chatterjee', 'couple'],  ['Nandini',   'Dutta',       'Soumyajit',  'Dutta',      'couple'],];// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// Compound name corrections ΓÇö when a nickname in a compound entry resolves to// the wrong member, redirect to the correct one.// This handles cases like "Soumyajit/ Nandita" where "Nandita" is a nickname// for Nandini Dutta but would otherwise match Nandita Guin exactly.// Each entry: { inCompoundWith, wrongFirst, correctFirst, correctLast }// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst COMPOUND_NAME_CORRECTIONS = [  { inCompoundWith: 'Soumyajit', wrongFirst: 'Nandita', correctFirst: 'Nandini', correctLast: 'Dutta' },];// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// CLI args// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst ARGS = process.argv.slice(2).reduce((a, s) => {  const [k, ...v] = s.replace(/^--/, '').split('=');  a[k] = v.join('=') || true;  return a;}, {});const DO_FIX   = ARGS.fix === true;const VERBOSE  = ARGS.verbose === true;const FILTER   = ARGS.member || null;  // single member filter// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// Helpers// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇfunction norm(s)  { return (s || '').toLowerCase().replace(/\s+/g, ' ').trim(); }function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }function esc(s)   { return (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }/** Remove Bengali honorifics Da/Di/Dada/Didi */function stripHonorifics(s) {  return (s || '').replace(/\b(da|di|dada|didi|uncle|aunty|auntie)\b/gi, '').trim();}/** * Levenshtein edit distance between two strings. * Used for fuzzy first-name matching (NandiniΓåöNadini, MoushumiΓåöMousumi, etc.) */function editDistance(a, b) {  const m = a.length, n = b.length;  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));  for (let i = 0; i <= m; i++) dp[i][0] = i;  for (let j = 0; j <= n; j++) dp[0][j] = j;  for (let i = 1; i <= m; i++) {    for (let j = 1; j <= n; j++) {      dp[i][j] = a[i - 1] === b[j - 1]        ? dp[i - 1][j - 1]        : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);    }  }  return dp[m][n];}/** Check if two first names are fuzzy-matches (edit distance Γëñ threshold, scaled by length) */function fuzzyFirstNameMatch(a, b) {  if (!a || !b) return false;  a = norm(a); b = norm(b);  if (a === b) return true;  if (a.length < 4 || b.length < 4) return false;  // too short for fuzzy  const maxLen = Math.max(a.length, b.length);  const threshold = maxLen <= 6 ? 1 : 2;  // allow 1 edit for short names, 2 for longer  return editDistance(a, b) <= threshold;}/** * Check if a resolved compound-name member should be corrected. * When "Nandita" in "Soumyajit/Nandita" resolves to Nandita Guin, * but it should be Nandini Dutta (nickname), apply correction. * @param {string[]} resolvedFirstNames - all resolved first names in this compound * @param {string} firstName - the first name being checked * @param {MemberIndex} index - member index for looking up the correct member * @returns {Object|null} corrected member, or null if no correction */function applyCompoundNameCorrection(resolvedFirstNames, firstName, index) {  const fn = norm(firstName);  for (const corr of COMPOUND_NAME_CORRECTIONS) {    if (norm(corr.wrongFirst) !== fn) continue;    // Check if the compound also contains the trigger name    if (resolvedFirstNames.some(n => norm(n) === norm(corr.inCompoundWith))) {      const correct = index.findByFirstName(corr.correctFirst, corr.correctLast);      if (correct.length === 1) {        console.log(`   ≡ƒöº Compound correction: "${firstName}" ΓåÆ "${corr.correctFirst} ${corr.correctLast}" (was resolving to wrong member)`);        return correct[0];      }    }  }  return null;}/** Generate a unique family ID (no collisions) */const _usedFamilyIds = new Set();function generateFamilyId() {  let id;  do {    const suffix = crypto.randomBytes(4).toString('hex').substring(0, 5).toUpperCase();    id = `FAM-2026-${suffix}`;  } while (_usedFamilyIds.has(id));  _usedFamilyIds.add(id);  return id;}/** Walk directory for files with given extensions */function walkDir(dir, exts) {  const results = [];  if (!fs.existsSync(dir)) return results;  for (const entry of fs.readdirSync(dir)) {    const full = path.join(dir, entry);    try {      const stat = fs.statSync(full);      if (stat.isDirectory()) {        results.push(...walkDir(full, exts));      } else if (exts.some(ext => entry.toLowerCase().endsWith(ext))) {        results.push(full);      }    } catch (_) {}  }  return results;}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// API functions// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function apiGet(endpoint, params = {}) {  const qs = new URLSearchParams({ ...params, admin_key: ADMIN_KEY }).toString();  const res = await fetch(`${API_BASE}/${endpoint}?${qs}`, { headers: API_HDRS });  if (!res.ok) throw new Error(`GET ${endpoint} ΓåÆ ${res.status}`);  return res.json();}async function apiPost(endpoint, body) {  const res = await fetch(`${API_BASE}/${endpoint}?admin_key=${encodeURIComponent(ADMIN_KEY)}`, {    method: 'POST',    headers: API_HDRS,    body: JSON.stringify(body)  });  if (!res.ok) throw new Error(`POST ${endpoint} ΓåÆ ${res.status}: ${await res.text().catch(() => '')}`);  return res.json();}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// STRICT name matching ΓÇö no bare-surname matches// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ/** * Check if a text mentions a person's name STRICTLY. * - Full name (first+last) ΓåÆ always accepted * - firstName alone ΓåÆ only if >= 4 chars * - lastName alone ΓåÆ NEVER accepted (too ambiguous: "Ghosh", "Roy") */function textMentionsFirstName(text, firstName) {  if (!text || !firstName) return false;  const t = norm(text);  const fn = norm(firstName);  if (fn.length < 3) return false;  // Word boundary check for short names (3 chars)  if (fn.length === 3) {    return new RegExp('\\b' + fn.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b').test(t);  }  return t.includes(fn);}function textMentionsFullName(text, firstName, lastName) {  if (!text || !firstName || !lastName) return false;  const t = norm(text);  const full = norm(`${firstName} ${lastName}`);  if (full.length < 5) return false;  return t.includes(full);}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// EVIDENCE GRAPH ΓÇö weighted undirected graph of member pairs// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇclass EvidenceGraph {  constructor() {    this.edges = new Map();    // "memberIdA|memberIdB" ΓåÆ { weight, evidence[] }    this.nodes = new Set();  }  _key(a, b) {    return a < b ? `${a}|${b}` : `${b}|${a}`;  // canonical order  }  addEvidence(memberA, memberB, weight, source, detail) {    if (memberA === memberB) return;    this.nodes.add(memberA);    this.nodes.add(memberB);    const key = this._key(memberA, memberB);    if (!this.edges.has(key)) {      this.edges.set(key, { weight: 0, evidence: [] });    }    const edge = this.edges.get(key);    edge.weight += weight;    edge.evidence.push({ source, detail, weight });  }  getEdge(a, b) {    return this.edges.get(this._key(a, b)) || { weight: 0, evidence: [] };  }  /** Find connected components where all edges in the component have weight >= threshold */  findFamilies(threshold) {    // Build adjacency list with edges meeting threshold    const adj = new Map();    for (const nodeId of this.nodes) adj.set(nodeId, new Set());    for (const [key, edge] of this.edges) {      if (edge.weight >= threshold) {        const [a, b] = key.split('|');        adj.get(a).add(b);        adj.get(b).add(a);      }    }    // BFS to find connected components    const visited = new Set();    const families = [];    for (const nodeId of this.nodes) {      if (visited.has(nodeId)) continue;      const component = [];      const queue = [nodeId];      while (queue.length > 0) {        const current = queue.shift();        if (visited.has(current)) continue;        visited.add(current);        component.push(current);        for (const neighbor of adj.get(current) || []) {          if (!visited.has(neighbor)) queue.push(neighbor);        }      }      families.push(component);    }    return families;  }  /** Get all evidence for a given member */  getEvidenceFor(memberId) {    const result = [];    for (const [key, edge] of this.edges) {      const [a, b] = key.split('|');      if (a === memberId || b === memberId) {        const other = a === memberId ? b : a;        result.push({ other, weight: edge.weight, evidence: edge.evidence });      }    }    return result.sort((a, b) => b.weight - a.weight);  }}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// MEMBER INDEX ΓÇö fast lookup by firstName, lastName, email, displayName// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇclass MemberIndex {  constructor(members) {    this.members = members;    this.byId = new Map();    this.byFirstName = new Map();  // normalized firstName ΓåÆ [member, ...]    this.byEmail = new Map();    this.byLastName = new Map();    this.nameOccurrences = new Map(); // norm(firstName) ΓåÆ Map<memberId, count>    for (const m of members) {      this.byId.set(m.memberId, m);      const fn = norm(m.firstName);      if (fn && fn.length >= 3) {        if (!this.byFirstName.has(fn)) this.byFirstName.set(fn, []);        this.byFirstName.get(fn).push(m);      }      const email = norm(m.email);      if (email) this.byEmail.set(email, m);      const ln = norm(m.lastName);      if (ln) {        // Normalize surname variants (Ghosh/Basu Ghosh, Ray/Roy, etc.)        const baseLn = this._baseSurname(ln);        if (!this.byLastName.has(baseLn)) this.byLastName.set(baseLn, []);        this.byLastName.get(baseLn).push(m);      }    }  }  _baseSurname(ln) {    // Normalize spelling variants    return ln.replace(/\s*\(.*?\)\s*/g, '')   // remove parentheticals             .replace(/^\.\s*/, '')            // remove leading dots             .replace(/\bchakravar\w*/i, 'chakraborty')             .replace(/\bchakrabor\w*/i, 'chakraborty')             .replace(/\broycho\w*/i, 'roychoudhury')             .replace(/\braychaud\w*/i, 'roychoudhury')             .replace(/\bmazumda\w*/i, 'majumdar')             .replace(/\bmajumde\w*/i, 'majumdar')             .replace(/\bchatto\w*/i, 'chatterjee')             .replace(/\bbanner\w*/i, 'banerjee')             .replace(/\bbhattachar\w*/i, 'bhattacharya')             .replace(/\bmondal/i, 'mandal')             .replace(/\bdutta\b/i, 'dutta')             .replace(/\bdatta\b/i, 'dutta')   // Datta ΓåÆ Dutta for grouping             .trim();  }  /** Find CRM member matching a given name (strict first, fuzzy fallback) */  findByFirstName(firstName, lastName) {    const fn = norm(stripHonorifics(firstName));    if (fn.length < 3) return [];    // 1) Exact first-name match    let candidates = this.byFirstName.get(fn) || [];    // 2) Fuzzy fallback: scan all first names for close matches (edit distance Γëñ threshold)    if (candidates.length === 0 && fn.length >= 4) {      for (const [key, members] of this.byFirstName) {        if (fuzzyFirstNameMatch(fn, key)) {          candidates = candidates.concat(members);        }      }    }    if (!lastName || norm(lastName).length < 2) return candidates;    // Filter by lastName using normalized surname comparison (Mondal=Mandal, etc.)    const targetLn = this._baseSurname(norm(lastName));    const exact = candidates.filter(m => {      const mLn = this._baseSurname(norm(m.lastName));      return mLn === targetLn || mLn.includes(targetLn) || targetLn.includes(mLn);    });    // Don't fallback to all candidates ΓÇö ambiguous matches create false positives    return exact;  }  /**   * Record a confident name resolution for occurrence-based disambiguation.   * Call this every time a firstName unambiguously resolves to a specific member.   */  recordResolution(firstName, memberId) {    const fn = norm(stripHonorifics(firstName));    if (!fn || fn.length < 3) return;    if (!this.nameOccurrences.has(fn)) this.nameOccurrences.set(fn, new Map());    const occ = this.nameOccurrences.get(fn);    occ.set(memberId, (occ.get(memberId) || 0) + 1);  }  /**   * When multiple candidates match a firstName, use prior occurrence counts   * to disambiguate. Returns the best candidate or null if inconclusive.   * Requires: the winner has ΓëÑ2 prior resolutions AND ΓëÑ2x the runner-up.   */  disambiguateByOccurrence(firstName, candidates) {    const fn = norm(stripHonorifics(firstName));    const occ = this.nameOccurrences.get(fn);    if (!occ || occ.size === 0) return null;    let best = null, bestCount = 0, secondBestCount = 0;    for (const c of candidates) {      const count = occ.get(c.memberId) || 0;      if (count > bestCount) {        secondBestCount = bestCount;        best = c;        bestCount = count;      } else if (count > secondBestCount) {        secondBestCount = count;      }    }    // Clear winner: at least 2 occurrences and ΓëÑ2x the runner-up    if (best && bestCount >= 2 && bestCount >= 2 * Math.max(secondBestCount, 1)) {      return best;    }    return null;  }  /** Find member by email */  findByEmail(email) {    return this.byEmail.get(norm(email)) || null;  }}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// PRE-SCAN ΓÇö build occurrence map before collectors run// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ/** * Quick scan of ALL compound name entries across ALL XLSX files. * Resolves only UNAMBIGUOUS names (single match) and records them * in the index's nameOccurrences map. This gives disambiguation * context to the collectors that run afterward. * * Example: if "Barnali Debu" appears as a full name 3 times, then * when "Barnali & Chiradip" is encountered (no surname), the * occurrence map helps pick Barnali Debu over Barnali Mondal. */function prescanOccurrenceMap(index, xlsxFiles) {  for (const fp of xlsxFiles) {    let wb;    try { wb = XLSX.readFile(fp, { cellDates: true }); } catch (_) { continue; }    for (const sheetName of wb.SheetNames) {      let rows;      try { rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], { defval: '' }); } catch (_) { continue; }      for (const row of rows) {        // All possible name fields        const nameFields = [          row['Name Entry'], row['Name'], row['Original Entry'],          row['Contributor'], row['rawNameEntry']        ].filter(Boolean);        for (const nameField of nameFields) {          // Both compound and non-compound entries help build context          const parts = nameField.match(/[/&+]|\band\b/i)            ? nameField.split(/[/&+]|\band\b/i).map(p => stripHonorifics(p).trim()).filter(p => p.length >= 2)            : [stripHonorifics(nameField).trim()];          // Extract shared surname (same logic as collectors)          let sharedSurname = '';          for (const part of parts) {            const words = part.split(/\s+/);            if (words.length >= 2) {              const possibleLn = words[words.length - 1];              if (possibleLn.length >= 3 && possibleLn[0] === possibleLn[0].toUpperCase()) {                sharedSurname = possibleLn;                break;              }            }          }          for (const part of parts) {            const words = part.split(/\s+/).filter(w => w.length >= 2);            if (!words[0]) continue;            const fn = words[0];            const ln = words.length > 1 ? words[words.length - 1] : sharedSurname;            // Only record when resolution is UNAMBIGUOUS (exactly 1 match)            const matches = index.findByFirstName(fn, ln);            if (matches.length === 1) {              index.recordResolution(fn, matches[0].memberId);            }          }        }        // Also count First Name / Last Name fields (Family Members rows)        const fn = (row['First Name'] || '').trim();        const ln = (row['Last Name'] || row['Primary Surname'] || '').trim();        if (fn && fn.length >= 2) {          const matches = index.findByFirstName(fn, ln);          if (matches.length === 1) {            index.recordResolution(fn, matches[0].memberId);          }        }      }    }  }}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// EVIDENCE COLLECTORS ΓÇö each function adds edges to the graph// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ/** * Source 1: Compound names in payment/membership XLSX * Parses entries like "Ranadhir Da/ Moumita Di" and links the two people. */function collectCompoundNameEvidence(graph, index, xlsxFiles) {  let count = 0;  for (const fp of xlsxFiles) {    let wb;    try { wb = XLSX.readFile(fp, { cellDates: true }); } catch (_) { continue; }    const filename = path.basename(fp);    for (const sheetName of wb.SheetNames) {      let rows;      try { rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], { defval: '' }); } catch (_) { continue; }      for (const row of rows) {        // Fields that may contain compound names        const nameFields = [          row['Name Entry'], row['Name'], row['Original Entry'],          row['Contributor'], row['rawNameEntry']        ].filter(Boolean);        for (const nameField of nameFields) {          // Check if it contains a separator          if (!nameField.match(/[/&+]|\band\b/i)) continue;          // Split on separators          const parts = nameField.split(/[/&+]|\band\b/i)            .map(p => stripHonorifics(p).trim())            .filter(p => p.length >= 2);          if (parts.length < 2) continue;          // Try to extract a shared surname from the entry          let sharedSurname = '';          // Check if any part contains a full name (first + last)          for (const part of parts) {            const words = part.split(/\s+/);            if (words.length >= 2) {              const possibleLn = words[words.length - 1];              if (possibleLn.length >= 3 && possibleLn[0] === possibleLn[0].toUpperCase()) {                sharedSurname = possibleLn;                break;              }            }          }          // Also check the full entry for a trailing surname          // Strip separators AND honorifics first; don't use a part's first name as surname          if (!sharedSurname) {            const fullWords = nameField.replace(/[/&+]/g, ' ').replace(/\b(da|di|dada|didi|and)\b/gi, '').trim().split(/\s+/);            const last = fullWords[fullWords.length - 1];            const partFirstNames = parts.map(p => norm(p.split(/\s+/)[0]));            if (last && last.length >= 3 && last[0] === last[0].toUpperCase() &&                !last.match(/^(Da|Di|And)$/i) && !partFirstNames.includes(norm(last))) {              sharedSurname = last;            }          }          // Find CRM members for each part          const resolved = [];          const resolvedFirstNames = [];          for (const part of parts) {            const partWords = part.split(/\s+/).filter(w => w.length >= 2);            const firstName = partWords[0] || '';            const lastName = partWords.length > 1 ? partWords[partWords.length - 1] : sharedSurname;            resolvedFirstNames.push(firstName);            const matches = index.findByFirstName(firstName, lastName);            if (matches.length === 1) {              resolved.push({ member: matches[0], firstName });              index.recordResolution(firstName, matches[0].memberId);            } else if (matches.length > 1) {              // Multiple candidates ΓÇö try occurrence-based disambiguation              const byOcc = index.disambiguateByOccurrence(firstName, matches);              if (byOcc) {                resolved.push({ member: byOcc, firstName });                index.recordResolution(firstName, byOcc.memberId);              }              // If still ambiguous, skip to avoid false positives            }          }          // Apply compound name corrections (e.g., "Nandita" ΓåÆ Nandini Dutta          // when in compound with "Soumyajit")          const allFirstNames = parts.map(p => (p.split(/\s+/)[0] || '').trim());          for (let ri = 0; ri < resolved.length; ri++) {            const corrected = applyCompoundNameCorrection(allFirstNames, resolved[ri].firstName, index);            if (corrected) {              resolved[ri] = { member: corrected, firstName: resolved[ri].firstName };            }          }          // Add edges between all resolved members in this compound entry          for (let i = 0; i < resolved.length; i++) {            for (let j = i + 1; j < resolved.length; j++) {              const isPayment = /membership/i.test(filename) || /payment/i.test(sheetName);              const weight = isPayment ? WEIGHT.COMPOUND_PAYMENT_NAME : WEIGHT.COMPOUND_XLSX_NAME;              graph.addEvidence(                resolved[i].member.memberId, resolved[j].member.memberId,                weight,                'compound_name',                `"${nameField}" in ${filename}/${sheetName}`              );              count++;            }          }        }      }    }  }  return count;}/** * Source 2: Family Members sheet ΓÇö shared compound Original Entry * When two members' Original Entry field is the SAME compound name, * they are in the same household. */function collectFamilyMembersEvidence(graph, index, xlsxFiles) {  let count = 0;  for (const fp of xlsxFiles) {    if (!/family.*universe/i.test(path.basename(fp))) continue;    let wb;    try { wb = XLSX.readFile(fp, { cellDates: true }); } catch (_) { continue; }    const sheet = wb.Sheets['Family Members'];    if (!sheet) continue;    let rows;    try { rows = XLSX.utils.sheet_to_json(sheet, { defval: '' }); } catch (_) { continue; }    // Group rows by their Original Entry (compound names)    const byOrigEntry = new Map();    for (const row of rows) {      const orig = (row['Original Entry'] || '').trim();      if (!orig) continue;      if (!byOrigEntry.has(orig)) byOrigEntry.set(orig, []);      byOrigEntry.get(orig).push(row);    }    // For each Original Entry group, link CRM members    for (const [origEntry, memberRows] of byOrigEntry) {      // Only compound entries create family evidence      if (!origEntry.match(/[/&+]|\band\b/i) && memberRows.length < 2) continue;      const resolved = [];      for (const row of memberRows) {        const fn = (row['First Name'] || '').trim();        const ln = (row['Last Name'] || row['Primary Surname'] || '').trim();        if (!fn || fn.length < 2) continue;        const matches = index.findByFirstName(fn, ln);        if (matches.length === 1) {          resolved.push(matches[0]);          index.recordResolution(fn, matches[0].memberId);        } else if (matches.length > 1) {          // Disambiguate: try surname first, then occurrence count          if (ln) {            const baseLn = index._baseSurname(norm(ln));            const exact = matches.filter(m => index._baseSurname(norm(m.lastName)) === baseLn);            if (exact.length === 1) {              resolved.push(exact[0]);              index.recordResolution(fn, exact[0].memberId);              continue;            }          }          // Fallback: occurrence-based disambiguation          const byOcc = index.disambiguateByOccurrence(fn, matches);          if (byOcc) {            resolved.push(byOcc);            index.recordResolution(fn, byOcc.memberId);          }        }      }      // Link all resolved members in this entry group      for (let i = 0; i < resolved.length; i++) {        for (let j = i + 1; j < resolved.length; j++) {          if (resolved[i].memberId === resolved[j].memberId) continue;          graph.addEvidence(            resolved[i].memberId, resolved[j].memberId,            WEIGHT.FAMILY_MEMBERS_SHARED,            'family_members_sheet',            `shared Original Entry "${origEntry}" in Family Members sheet`          );          count++;        }      }    }    // Also check Raw Entries for compound names linking CRM members    const rawSheet = wb.Sheets['Raw Entries'];    if (rawSheet) {      let rawRows;      try { rawRows = XLSX.utils.sheet_to_json(rawSheet, { defval: '' }); } catch (_) { continue; }      for (const row of rawRows) {        const nameEntry = (row['Name Entry'] || '').trim();        if (!nameEntry.match(/[/&+]|\band\b/i)) continue;        // Parse compound name parts        const parts = nameEntry.split(/[/&+]|\band\b/i)          .map(p => stripHonorifics(p).trim())          .filter(p => p.length >= 2);        if (parts.length < 2) continue;        // Extract shared surname        let sharedSurname = '';        for (const p of parts) {          const words = p.split(/\s+/);          if (words.length >= 2) { sharedSurname = words[words.length - 1]; break; }        }        // Fallback: trailing surname ΓÇö strip separators/honorifics, skip if matches a part's first name        if (!sharedSurname) {          const words = nameEntry.replace(/[/&+]/g, ' ').replace(/\b(da|di|dada|didi|and)\b/gi, '').trim().split(/\s+/);          const last = words[words.length - 1];          const partFirstNames = parts.map(p => norm(p.split(/\s+/)[0]));          if (last && last.length >= 3 && !partFirstNames.includes(norm(last))) sharedSurname = last;        }        const resolved = [];        for (const part of parts) {          const words = part.split(/\s+/).filter(w => w.length >= 2);          const fn = words[0] || '';          const ln = words.length > 1 ? words[words.length - 1] : sharedSurname;          const matches = index.findByFirstName(fn, ln);          if (matches.length === 1) {            resolved.push({ member: matches[0], firstName: fn });            index.recordResolution(fn, matches[0].memberId);          } else if (matches.length > 1) {            // Try surname disambiguation first            if (ln) {              const baseLn = index._baseSurname(norm(ln));              const exact = matches.filter(m => index._baseSurname(norm(m.lastName)) === baseLn);              if (exact.length === 1) {                resolved.push({ member: exact[0], firstName: fn });                index.recordResolution(fn, exact[0].memberId);                continue;              }            }            // Fallback: occurrence-based disambiguation            const byOcc = index.disambiguateByOccurrence(fn, matches);            if (byOcc) {              resolved.push({ member: byOcc, firstName: fn });              index.recordResolution(fn, byOcc.memberId);            }          }        }        // Apply compound name corrections        const rawAllFirstNames = parts.map(p => (p.split(/\s+/)[0] || '').trim());        for (let ri = 0; ri < resolved.length; ri++) {          const corrected = applyCompoundNameCorrection(rawAllFirstNames, resolved[ri].firstName, index);          if (corrected) {            resolved[ri] = { member: corrected, firstName: resolved[ri].firstName };          }        }        for (let i = 0; i < resolved.length; i++) {          for (let j = i + 1; j < resolved.length; j++) {            if (resolved[i].member.memberId === resolved[j].member.memberId) continue;            graph.addEvidence(              resolved[i].member.memberId, resolved[j].member.memberId,              WEIGHT.SAME_COMPOUND_RAW,              'raw_entries_compound',              `"${nameEntry}" in Raw Entries (${row['Year'] || ''})`            );            count++;          }        }      }    }  }  return count;}/** * Source 3: Jagriti contributor comments with explicit relationships * "Ranadhir da's daughter" on contributor Arundhuti ΓåÆ parent-child link */function collectJagritiRelationships(graph, index, xlsxFiles) {  let count = 0;  const relationships = []; // for report  for (const fp of xlsxFiles) {    if (!/jagriti/i.test(path.basename(fp))) continue;    let wb;    try { wb = XLSX.readFile(fp, { cellDates: true }); } catch (_) { continue; }    const filename = path.basename(fp);    for (const sheetName of wb.SheetNames) {      let rows;      try { rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], { defval: '' }); } catch (_) { continue; }      for (const row of rows) {        const comments = row['Comments'] || row['__EMPTY'] || row['Notes'] || '';        if (!comments) continue;        const contributor = (row['Contributor'] || row['Name'] || '').trim();        if (!contributor) continue;        // Pattern: "PersonName's daughter/son/wife/husband/father/mother/grand daughter"        const relPatterns = [          // "Ranadhir da's daughter" ΓåÆ Ranadhir is parent, contributor is child          /(\w[\w\s]*?)\s*(?:da|di|dada|didi)?['']s\s+(daughter|son|grand\s*daughter|grand\s*son|wife|husband|father|mother|sister|brother|child|kid|niece|nephew)/i,          // "daughter of Ranadhir" type patterns          /(daughter|son|wife|husband|father|mother|sister|brother)\s+of\s+(\w[\w\s]*?)(?:\s*$|[,.])/i,          // "X - Y's friend/relative"          /(\w[\w\s]*?)['']s\s+(friend|relative|family)/i,        ];        for (const pattern of relPatterns) {          const match = comments.match(pattern);          if (!match) continue;          let parentName, relationship;          if (pattern === relPatterns[1]) {            // "daughter of X" format            relationship = match[1];            parentName = stripHonorifics(match[2]).trim();          } else {            parentName = stripHonorifics(match[1]).trim();            relationship = match[2];          }          if (!parentName || parentName.length < 3) continue;          // Find the parent CRM member          const parentMatches = index.findByFirstName(parentName, '');          // Find the contributor CRM member          const contribFirstName = contributor.replace(/\s*\(.*?\)\s*/g, '').split(/\s+/)[0];          const contribMatches = index.findByFirstName(contribFirstName, '');          // If BOTH parent and contributor are CRM members ΓåÆ add graph edge          if (parentMatches.length >= 1 && contribMatches.length >= 1) {            const parent = parentMatches[0];            const child = contribMatches[0];            if (parent.memberId !== child.memberId) {              graph.addEvidence(                parent.memberId, child.memberId,                WEIGHT.JAGRITI_RELATIONSHIP,                'jagriti_comment',                `${filename}: "${contributor}" ΓÇö "${comments.substring(0, 80)}" (${relationship})`              );              count++;            }          }          // Always log the relationship for the report (even if child is not a CRM member)          if (parentMatches.length >= 1) {            const parent = parentMatches[0];            relationships.push({              parent: parent.displayName || `${parent.firstName} ${parent.lastName}`,              child: contributor,              relationship,              source: filename,              childInCRM: contribMatches.length > 0            });          }        }      }    }  }  return { count, relationships };}/** * Source 4: CRM Communications/Emails * Look for parent emails mentioning children's names ΓåÆ parent-child evidence */async function collectEmailEvidence(graph, index, members) {  let count = 0;  const batchSize = 5;  console.log(`   Scanning emails for ${members.length} members (in batches of ${batchSize})...`);  for (let i = 0; i < members.length; i += batchSize) {    const batch = members.slice(i, i + batchSize);    const results = await Promise.all(batch.map(async m => {      try {        const report = await apiGet('crm_member_report', { memberId: m.memberId });        const comms = (report.report && report.report.communications && report.report.communications.recent) || [];        return { member: m, comms };      } catch (_) {        return { member: m, comms: [] };      }    }));    for (const { member, comms } of results) {      if (comms.length === 0) continue;      for (const comm of comms) {        const text = norm(`${comm.subject || ''} ${comm.body || ''}`);        if (!text || text.length < 10) continue;        // Check if this email mentions another CRM member's first name        for (const other of members) {          if (other.memberId === member.memberId) continue;          // Only check members with same last name (potential family)          if (norm(member.lastName) !== norm(other.lastName) &&               norm(other.lastName).length > 0) continue;          const otherFn = norm(other.firstName);          if (otherFn.length < 4) continue;          if (text.includes(otherFn)) {            // Check for parent-child indicators            const isPerformance = /performance|recital|dance|song|poem|essay|story|art|drawing|painting|award|certificate|stage|participated|performed/i.test(text);            const isKidRelated = /child|kid|son|daughter|boy|girl|student/i.test(text);            if (isPerformance || isKidRelated) {              graph.addEvidence(                member.memberId, other.memberId,                WEIGHT.EMAIL_PARENT_CHILD,                'email_parent_child',                `Email "${(comm.subject || '').substring(0, 60)}" mentions ${other.firstName} (${comm.date || ''})`              );              count++;            }          }        }      }    }    if (i % 20 === 0 && i > 0) {      process.stdout.write(`   ... ${i}/${members.length} members scanned\r`);    }    await sleep(100); // rate limit  }  console.log(`   ... ${members.length}/${members.length} members scanned`);  return count;}/** * Source 5: Google Contacts ΓÇö same address = possible family */function collectGoogleContactsEvidence(graph, index) {  let count = 0;  const contactsPath = path.join(__dirname, 'google_contacts.json');  if (!fs.existsSync(contactsPath)) return count;  let contacts;  try {    contacts = JSON.parse(fs.readFileSync(contactsPath, 'utf8'));  } catch (_) { return count; }  // Build address ΓåÆ contacts map  const byAddress = new Map();  for (const c of (Array.isArray(contacts) ? contacts : contacts.contacts || [])) {    const addr = norm(c.address || c.formattedAddress || '');    if (!addr || addr.length < 10) continue;    const email = norm(c.email || '');    const crmMember = email ? index.findByEmail(email) : null;    if (!crmMember) continue;    if (!byAddress.has(addr)) byAddress.set(addr, []);    byAddress.get(addr).push(crmMember);  }  // Members sharing the same address ΓåÆ family evidence  for (const [addr, members] of byAddress) {    for (let i = 0; i < members.length; i++) {      for (let j = i + 1; j < members.length; j++) {        if (members[i].memberId === members[j].memberId) continue;        graph.addEvidence(          members[i].memberId, members[j].memberId,          WEIGHT.GOOGLE_SAME_ADDRESS,          'google_same_address',          `Shared address: "${addr.substring(0, 40)}..."`        );        count++;      }    }  }  return count;}/** * Source 6: Same email domain ΓÇö custom domain + same surname */function collectEmailDomainEvidence(graph, index, members) {  let count = 0;  const genericDomains = new Set([    'gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'aol.com',    'icloud.com', 'live.com', 'msn.com', 'mail.com', 'zoho.com',    'protonmail.com', 'yandex.com', 'gmx.com', 'me.com',    'yahoo.co.in', 'netzero.com', 'hotmail.co.in', 'fiu.edu',    'mayo.edu', 'test.com', 'wix.com'  ]);  // Group by custom email domain  const byDomain = new Map();  for (const m of members) {    const email = (m.email || '').toLowerCase();    if (!email.includes('@')) continue;    const domain = email.split('@')[1];    if (genericDomains.has(domain)) continue;    if (!byDomain.has(domain)) byDomain.set(domain, []);    byDomain.get(domain).push(m);  }  for (const [domain, domainMembers] of byDomain) {    if (domainMembers.length < 2) continue;    for (let i = 0; i < domainMembers.length; i++) {      for (let j = i + 1; j < domainMembers.length; j++) {        const a = domainMembers[i], b = domainMembers[j];        // Same custom domain ΓåÆ possible family        graph.addEvidence(          a.memberId, b.memberId,          WEIGHT.SAME_EMAIL_DOMAIN,          'same_email_domain',          `Both use @${domain}`        );        count++;      }    }  }  return count;}/** * Source 7: CRM Payment entries with compound rawNameEntry */async function collectPaymentEvidence(graph, index, members) {  let count = 0;  console.log(`   Scanning payments for ${members.length} members...`);  for (let i = 0; i < members.length; i += 10) {    const batch = members.slice(i, i + 10);    const results = await Promise.all(batch.map(async m => {      try {        const data = await apiGet('crm_member_payments', { memberId: m.memberId });        return { member: m, payments: data.payments || data.items || [] };      } catch (_) {        return { member: m, payments: [] };      }    }));    for (const { member, payments } of results) {      for (const payment of payments) {        const rawName = payment.rawNameEntry || payment.payerName || '';        if (!rawName.match(/[/&+]|\band\b/i)) continue;        const parts = rawName.split(/[/&+]|\band\b/i)          .map(p => stripHonorifics(p).trim())          .filter(p => p.length >= 2);        if (parts.length < 2) continue;        const resolved = [];        for (const part of parts) {          const words = part.split(/\s+/).filter(w => w.length >= 2);          const fn = words[0] || '';          const ln = words.length > 1 ? words[words.length - 1] : '';          const matches = index.findByFirstName(fn, ln);          if (matches.length === 1) {            resolved.push(matches[0]);            index.recordResolution(fn, matches[0].memberId);          } else if (matches.length > 1) {            // Try surname disambiguation first            if (ln) {              const baseLn = index._baseSurname(norm(ln));              const exact = matches.filter(m => index._baseSurname(norm(m.lastName)) === baseLn);              if (exact.length === 1) {                resolved.push(exact[0]);                index.recordResolution(fn, exact[0].memberId);                continue;              }            }            // Fallback: occurrence-based disambiguation            const byOcc = index.disambiguateByOccurrence(fn, matches);            if (byOcc) {              resolved.push(byOcc);              index.recordResolution(fn, byOcc.memberId);            }          }        }        for (let x = 0; x < resolved.length; x++) {          for (let y = x + 1; y < resolved.length; y++) {            if (resolved[x].memberId === resolved[y].memberId) continue;            graph.addEvidence(              resolved[x].memberId, resolved[y].memberId,              WEIGHT.COMPOUND_PAYMENT_NAME,              'payment_compound_name',              `Payment rawName "${rawName}" (${payment.paymentYear || ''})`            );            count++;          }        }      }    }    if (i % 30 === 0 && i > 0) process.stdout.write(`   ... ${i}/${members.length}\r`);    await sleep(100);  }  console.log(`   ... ${members.length}/${members.length} payments scanned`);  return count;}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// MANUAL OVERRIDES ΓÇö admin-confirmed family relationships// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ/** * Apply manual overrides for known family relationships that the automated * evidence collection cannot detect (e.g., cross-surname couples with no * compound name entries in any data source). */function applyManualOverrides(graph, index) {  let count = 0;  for (const [fn1, ln1, fn2, ln2, relationship] of MANUAL_OVERRIDES) {    const m1 = index.findByFirstName(fn1, ln1);    const m2 = index.findByFirstName(fn2, ln2);    if (m1.length !== 1 || m2.length !== 1) {      console.log(`\n   ΓÜá Manual override skipped: ${fn1} ${ln1} ΓåÆ ${m1.length} matches, ${fn2} ${ln2} ΓåÆ ${m2.length} matches`);      continue;    }    graph.addEvidence(      m1[0].memberId, m2[0].memberId,      100,  // Very high weight ΓÇö admin-confirmed      'manual_override',      `Admin-confirmed ${relationship}: ${fn1} ${ln1} + ${fn2} ${ln2}`    );    count++;  }  return count;}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// FAMILY TYPE INFERENCE// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction inferFamilyType(memberGroup) {  if (memberGroup.length === 1) return 'individual';  if (memberGroup.length === 2) return 'couple';  return 'family'; // 3+ members}function inferFamilyDisplayName(memberGroup) {  // Find the primary surname (most common)  const surnameCount = {};  for (const m of memberGroup) {    const ln = (m.lastName || '').replace(/\s*\(.*?\)\s*/g, '').trim();    if (ln) surnameCount[ln] = (surnameCount[ln] || 0) + 1;  }  const primarySurname = Object.entries(surnameCount).sort((a, b) => b[1] - a[1])[0]?.[0] || '';  if (memberGroup.length === 1) {    return `${memberGroup[0].firstName} ${primarySurname}`.trim();  } else if (memberGroup.length === 2) {    return `${memberGroup[0].firstName} & ${memberGroup[1].firstName} ${primarySurname}`.trim();  } else {    return `${primarySurname} Family (${memberGroup.length})`;  }}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// DIFF GENERATOR ΓÇö compare old vs new family assignments// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction computeDiff(members, newFamilies, memberToNewFamily) {  const changes = [];  const unchanged = [];  // Group members by their CURRENT familyId  const oldGroups = new Map();  for (const m of members) {    const fam = m.familyId || 'NO_FAMILY';    if (!oldGroups.has(fam)) oldGroups.set(fam, []);    oldGroups.get(fam).push(m);  }  for (const m of members) {    const oldFam = m.familyId || 'NO_FAMILY';    const newFam = memberToNewFamily.get(m.memberId) || 'UNASSIGNED';    const newGroupMembers = newFamilies.get(newFam) || [];    const oldGroupMembers = oldGroups.get(oldFam) || [];    // Check if the group composition changed    const oldSet = new Set(oldGroupMembers.map(x => x.memberId));    const newSet = new Set(newGroupMembers.map(x => x.memberId));    const sameGroup = oldSet.size === newSet.size && [...oldSet].every(id => newSet.has(id));    if (sameGroup && oldFam === newFam) {      unchanged.push(m);    } else {      changes.push({        memberId: m.memberId,        name: `${m.firstName} ${m.lastName}`.trim(),        email: m.email,        oldFamilyId: oldFam,        newFamilyId: newFam,        oldGroupSize: oldGroupMembers.length,        newGroupSize: newGroupMembers.length,        oldGroupNames: oldGroupMembers.map(x => `${x.firstName} ${x.lastName}`.trim()),        newGroupNames: newGroupMembers.map(x => `${x.firstName} ${x.lastName}`.trim()),      });    }  }  return { changes, unchanged };}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// HTML REPORT GENERATOR// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction generateReport(members, graph, newFamilies, memberToNewFamily, diff, jagritiRels) {  const { changes } = diff;  // Group changes by newFamilyId  const changesByFamily = new Map();  for (const c of changes) {    if (!changesByFamily.has(c.newFamilyId)) changesByFamily.set(c.newFamilyId, []);    changesByFamily.get(c.newFamilyId).push(c);  }  // Build stats  const oldFamilyCount = new Set(members.map(m => m.familyId || 'NONE')).size;  const newFamilyCount = newFamilies.size;  const membersAffected = changes.length;  const affectedFamilies = new Set(changes.map(c => c.oldFamilyId)).size;  let html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>BANF Family Fix Report</title><style>  * { box-sizing: border-box; margin: 0; padding: 0; }  body { font-family: 'Segoe UI', system-ui, sans-serif; background: #0d1117; color: #c9d1d9; padding: 24px; }  h1, h2, h3 { color: #58a6ff; }  h1 { font-size: 1.8rem; margin-bottom: 8px; }  h2 { font-size: 1.3rem; margin: 24px 0 12px; border-bottom: 1px solid #30363d; padding-bottom: 6px; }  h3 { font-size: 1.1rem; margin: 16px 0 8px; color: #79c0ff; }  .stats { display: flex; gap: 16px; flex-wrap: wrap; margin: 16px 0; }  .stat-card { background: #161b22; border: 1px solid #30363d; border-radius: 8px; padding: 16px 20px; min-width: 160px; }  .stat-val { font-size: 2rem; font-weight: bold; color: #58a6ff; }  .stat-label { font-size: 0.85rem; color: #8b949e; margin-top: 4px; }  table { width: 100%; border-collapse: collapse; margin: 12px 0; }  th, td { padding: 8px 12px; text-align: left; border-bottom: 1px solid #21262d; }  th { color: #8b949e; font-size: 0.85rem; text-transform: uppercase; }  tr:hover { background: #161b22; }  .badge { display: inline-block; padding: 2px 8px; border-radius: 12px; font-size: 0.75rem; font-weight: 600; }  .badge-fix  { background: #1f6feb33; color: #58a6ff; }  .badge-ok   { background: #23863533; color: #3fb950; }  .badge-warn { background: #9e6a0333; color: #e3b341; }  .badge-err  { background: #da363333; color: #f85149; }  .family-card { background: #161b22; border: 1px solid #30363d; border-radius: 8px; padding: 16px; margin: 12px 0; }  .family-card.changed { border-left: 3px solid #58a6ff; }  .family-card.unchanged { border-left: 3px solid #3fb950; opacity: 0.7; }  .evidence-list { margin: 8px 0 0 16px; font-size: 0.85rem; color: #8b949e; }  .evidence-list li { margin: 3px 0; }  .arrow { color: #f0883e; font-weight: bold; margin: 0 8px; }  .old-group { color: #f85149; text-decoration: line-through; opacity: 0.7; }  .new-group { color: #3fb950; font-weight: 600; }  .member-name { color: #c9d1d9; }  .section { margin-bottom: 32px; }  .rel-tag { color: #d2a8ff; font-size: 0.8rem; }  .weight { color: #79c0ff; font-size: 0.8rem; }  footer { margin-top: 40px; padding-top: 16px; border-top: 1px solid #21262d; color: #484f58; font-size: 0.8rem; }</style></head><body><h1>BANF Family Fix Report</h1><p style="color:#8b949e;margin-bottom:20px">Generated ${new Date().toISOString().replace('T', ' ').substring(0, 19)} &bull; Evidence-based family regrouping</p><div class="stats">  <div class="stat-card"><div class="stat-val">${members.length}</div><div class="stat-label">Total Members</div></div>  <div class="stat-card"><div class="stat-val">${oldFamilyCount}</div><div class="stat-label">Current Families</div></div>  <div class="stat-card"><div class="stat-val">${newFamilyCount}</div><div class="stat-label">Corrected Families</div></div>  <div class="stat-card"><div class="stat-val">${membersAffected}</div><div class="stat-label">Members Affected</div></div>  <div class="stat-card"><div class="stat-val">${affectedFamilies}</div><div class="stat-label">Families Changed</div></div>  <div class="stat-card"><div class="stat-val">${graph.edges.size}</div><div class="stat-label">Evidence Edges</div></div></div>`;  // ΓöÇΓöÇΓöÇ Section: Problem Families (currently wrong) ΓöÇΓöÇΓöÇ  // Find families where the current grouping differs from the evidence-based grouping  const problematicOldFamilies = new Map();  for (const c of changes) {    if (!problematicOldFamilies.has(c.oldFamilyId)) {      problematicOldFamilies.set(c.oldFamilyId, { members: [], newFamilies: new Set() });    }    problematicOldFamilies.get(c.oldFamilyId).members.push(c);    problematicOldFamilies.get(c.oldFamilyId).newFamilies.add(c.newFamilyId);  }  // Sort: families that SPLIT into multiple new families first (most wrong)  const sortedProblems = [...problematicOldFamilies.entries()]    .sort((a, b) => b[1].newFamilies.size - a[1].newFamilies.size);  html += `<div class="section"><h2>≡ƒöì Problem Families ΓÇö Current Groupings That Need Fixing</h2>`;  for (const [oldFam, info] of sortedProblems) {    const splitCount = info.newFamilies.size;    const badge = splitCount > 1 ? 'badge-err' : 'badge-fix';    const label = splitCount > 1 ? `Splits into ${splitCount} families` : 'Regrouped';    html += `<div class="family-card changed">      <h3>${esc(oldFam)} <span class="badge ${badge}">${label}</span></h3>      <p style="color:#8b949e;font-size:0.85rem">Currently ${info.members.length} member(s) ΓÇö ${splitCount > 1 ? 'INCORRECTLY grouped together' : 'needs reassignment'}</p>      <table>        <tr><th>Member</th><th>Email</th><th>Old Family</th><th></th><th>New Family</th><th>New Group</th></tr>`;    for (const c of info.members) {      html += `<tr>        <td class="member-name">${esc(c.name)}</td>        <td style="color:#8b949e;font-size:0.85rem">${esc(c.email)}</td>        <td class="old-group">${esc(c.oldFamilyId)}</td>        <td class="arrow">ΓåÆ</td>        <td class="new-group">${esc(c.newFamilyId)}</td>        <td style="font-size:0.85rem">${c.newGroupNames.map(n => esc(n)).join(', ')}</td>      </tr>`;    }    html += `</table>`;    // Show evidence for connections within new groups    const newFamIds = [...info.newFamilies];    for (const nfid of newFamIds) {      const membersInNewFam = changes.filter(c => c.newFamilyId === nfid);      if (membersInNewFam.length > 1) {        html += `<h3 style="margin-top:12px">Evidence for ${esc(nfid)}:</h3><ul class="evidence-list">`;        for (let i = 0; i < membersInNewFam.length; i++) {          for (let j = i + 1; j < membersInNewFam.length; j++) {            const edge = graph.getEdge(membersInNewFam[i].memberId, membersInNewFam[j].memberId);            if (edge.weight > 0) {              for (const ev of edge.evidence) {                html += `<li><span class="weight">[w=${ev.weight}]</span> ${esc(ev.source)}: ${esc(ev.detail)}</li>`;              }            }          }        }        html += `</ul>`;      }    }    html += `</div>`;  }  html += `</div>`;  // ΓöÇΓöÇΓöÇ Section: Correct Families (new groupings) ΓöÇΓöÇΓöÇ  html += `<div class="section"><h2>Γ£à Corrected Family Assignments (All ${newFamilyCount} families)</h2>`;  // Sort families by size descending  const sortedFamilies = [...newFamilies.entries()].sort((a, b) => b[1].length - a[1].length);  for (const [famId, memberList] of sortedFamilies) {    const type = inferFamilyType(memberList);    const displayName = inferFamilyDisplayName(memberList);    const isChanged = memberList.some(m => changes.find(c => c.memberId === m.memberId));    const cardClass = isChanged ? 'changed' : 'unchanged';    const badge = isChanged ? '<span class="badge badge-fix">changed</span>' : '<span class="badge badge-ok">ok</span>';    html += `<div class="family-card ${cardClass}">      <h3>${esc(famId)} ΓÇö ${esc(displayName)} ${badge} <span class="badge badge-warn">${type}</span></h3>      <table><tr><th>Member</th><th>Email</th><th>Previous Family</th></tr>`;    for (const m of memberList) {      html += `<tr>        <td class="member-name">${esc(m.firstName)} ${esc(m.lastName)}</td>        <td style="color:#8b949e;font-size:0.85rem">${esc(m.email)}</td>        <td style="font-size:0.85rem">${esc(m.familyId || 'none')}</td>      </tr>`;    }    html += `</table>`;    // Show intra-family evidence    if (memberList.length > 1) {      html += `<ul class="evidence-list">`;      for (let i = 0; i < memberList.length; i++) {        for (let j = i + 1; j < memberList.length; j++) {          const edge = graph.getEdge(memberList[i].memberId, memberList[j].memberId);          if (edge.weight > 0) {            for (const ev of edge.evidence) {              html += `<li><span class="weight">[w=${ev.weight}]</span> ${esc(ev.source)}: ${esc(ev.detail)}</li>`;            }          }        }      }      html += `</ul>`;    }    html += `</div>`;  }  html += `</div>`;  // ΓöÇΓöÇΓöÇ Section: Jagriti Relationships ΓöÇΓöÇΓöÇ  if (jagritiRels.length > 0) {    html += `<div class="section"><h2>≡ƒæ¿ΓÇì≡ƒæ⌐ΓÇì≡ƒæº Jagriti-Detected Family Relationships</h2>    <table><tr><th>Parent/Relative</th><th>Relationship</th><th>Person</th><th>Source</th></tr>`;    for (const r of jagritiRels) {      html += `<tr>        <td>${esc(r.parent)}</td>        <td><span class="rel-tag">${esc(r.relationship)}</span></td>        <td>${esc(r.child)}</td>        <td style="color:#8b949e;font-size:0.85rem">${esc(r.source)}</td>      </tr>`;    }    html += `</table></div>`;  }  html += `<footer>BANF Family Fix Agent v1.0 &bull; Evidence threshold: ${FAMILY_THRESHOLD} &bull; ${graph.edges.size} edges analyzed</footer></body></html>`;  return html;}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// CRM FIX ΓÇö Apply corrected family assignments// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉasync function applyFixes(members, newFamilies, memberToNewFamily) {  console.log('\n≡ƒöº Applying family fixes to CRM...');  let updated = 0, errors = 0;  // Step 1: Create new FamilyGroup records via crm_family_create  console.log('   Step 1: Creating new family groups...');  const createdFamilies = new Set();  for (const [famId, memberList] of newFamilies) {    // Check if this family ID already exists and needs no changes    const allSameFam = memberList.every(m => m.familyId === famId);    if (allSameFam) continue;    const familyType = inferFamilyType(memberList);    const displayName = inferFamilyDisplayName(memberList);    const primarySurname = memberList[0]?.lastName || '';    try {      // Try to create/update the family group      await apiPost('crm_family_update', {        familyId: famId,        displayName,        primarySurname,        familyType,        membershipStatus: 'active',        notes: `Auto-corrected by family-fix-agent on ${new Date().toISOString().substring(0, 10)}`      });      createdFamilies.add(famId);    } catch (e) {      // Family doesn't exist yet ΓåÆ create it      try {        // We can't create with existing members via API easily,        // so we'll create a placeholder and update members individually        console.log(`   Creating family group ${famId}...`);        createdFamilies.add(famId);      } catch (e2) {        console.log(`   ΓÜá Could not create family ${famId}: ${e2.message}`);      }    }    await sleep(200);  }  // Step 2: Update each member's familyId and familyType  console.log('   Step 2: Updating member family assignments...');  for (const m of members) {    const newFam = memberToNewFamily.get(m.memberId);    if (!newFam || newFam === m.familyId) continue;    const newMembers = newFamilies.get(newFam) || [];    const newType = inferFamilyType(newMembers);    try {      // Update member ΓÇö familyType is in the allowed list      // Note: familyId is NOT in updateMemberInfo allowed list      // We update familyType, and output the full mapping for manual familyId fix      await apiPost('crm_member_update', {        memberId: m.memberId,        familyType: newType,        notes: `Family regrouped: ${m.familyId || 'none'} ΓåÆ ${newFam} by family-fix-agent`      });      updated++;      if (VERBOSE) console.log(`   Γ£à ${m.firstName} ${m.lastName}: ${m.familyId} ΓåÆ ${newFam} (type: ${newType})`);    } catch (e) {      console.log(`   Γ¥î ${m.memberId} (${m.firstName} ${m.lastName}): ${e.message}`);      errors++;    }    await sleep(150);  }  console.log(`\n   Updated: ${updated} members, Errors: ${errors}`);  console.log(`\n   ΓÜá NOTE: familyId field is not directly updatable via crm_member_update API.`);  console.log(`   The family-fix-mapping.json file contains the complete correct mapping.`);  console.log(`   To apply familyId changes, either:`);  console.log(`     1. Add 'familyId' to the allowed list in crm-agent.js updateMemberInfo()`);  console.log(`     2. Use bulk_import_members with the fix mapping`);  console.log(`     3. Apply directly in Wix data dashboard`);  return { updated, errors };}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// MAIN// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉasync function main() {  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  BANF Family Fix Agent v1.0');  console.log('  Intelligent co-occurrence-based family grouping');  console.log(`  Mode: ${DO_FIX ? '≡ƒöº FIX (will update CRM)' : '≡ƒöì DRY RUN (report only)'}`);  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ\n');  // ΓöÇΓöÇΓöÇ Phase 1: Data Collection ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  console.log('≡ƒôÑ Phase 1: Loading data sources...\n');  // 1a. Fetch all CRM members  console.log('   Fetching CRM members...');  const crmData = await apiGet('crm_members', { limit: 200 });  let members = crmData.members || crmData.items || [];  // Filter test/demo accounts  members = members.filter(m => {    const name = norm(`${m.firstName} ${m.lastName}`);    const email = norm(m.email);    return !name.includes('demo') && !name.includes('test') &&           !email.includes('demo') && !email.includes('test.com') &&           !email.includes('wix.com') &&           (m.firstName || m.lastName); // must have at least a name  });  console.log(`   Γ£ö ${members.length} active members loaded (filtered test accounts)\n`);  // 1b. Build member index  const index = new MemberIndex(members);  // 1c. Load all XLSX files  const xlsxFiles = walkDir(DATA_ROOT, ['.xlsx', '.xls']);  console.log(`   Γ£ö ${xlsxFiles.length} XLSX files found in ${DATA_ROOT}\n`);  // Apply single-member filter if requested  if (FILTER) {    const filteredMember = members.find(m =>      norm(m.firstName).includes(norm(FILTER)) ||      norm(m.lastName).includes(norm(FILTER)) ||      m.memberId === FILTER    );    if (!filteredMember) {      console.log(`Γ¥î Member "${FILTER}" not found.`);      process.exit(1);    }    console.log(`   ≡ƒöÄ Filtering for: ${filteredMember.firstName} ${filteredMember.lastName}\n`);  }  // ΓöÇΓöÇΓöÇ Phase 2: Evidence Collection ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  console.log('≡ƒöÄ Phase 2: Collecting family evidence...\n');  // Pre-scan: build occurrence map from ALL unambiguous compound entries  // This gives disambiguation context BEFORE collectors create edges  prescanOccurrenceMap(index, xlsxFiles);  const graph = new EvidenceGraph();  // Source 1: Compound names in XLSX (payment/membership entries)  process.stdout.write('   [1/7] Compound names in XLSX... ');  const compoundCount = collectCompoundNameEvidence(graph, index, xlsxFiles);  console.log(`${compoundCount} evidence edges`);  // Source 2: Family Members sheet  process.stdout.write('   [2/7] Family Members sheet... ');  const fmCount = collectFamilyMembersEvidence(graph, index, xlsxFiles);  console.log(`${fmCount} evidence edges`);  // Source 3: Jagriti relationship comments  process.stdout.write('   [3/7] Jagriti relationships... ');  const { count: jagCount, relationships: jagRels } = collectJagritiRelationships(graph, index, xlsxFiles);  console.log(`${jagCount} evidence edges (${jagRels.length} relationships)`);  if (jagRels.length > 0) {    for (const r of jagRels) {      console.log(`         ΓÇó ${r.parent} ΓåÆ ${r.child} (${r.relationship})`);    }  }  // Source 4: CRM emails  process.stdout.write('   [4/7] CRM email analysis... ');  const emailCount = await collectEmailEvidence(graph, index, members);  console.log(`${emailCount} evidence edges`);  // Source 5: Google Contacts  process.stdout.write('   [5/7] Google Contacts... ');  const gcCount = collectGoogleContactsEvidence(graph, index);  console.log(`${gcCount} evidence edges`);  // Source 6: Email domain analysis  process.stdout.write('   [6/7] Email domain analysis... ');  const edCount = collectEmailDomainEvidence(graph, index, members);  console.log(`${edCount} evidence edges`);  // Source 7: CRM payment compound names  process.stdout.write('   [7/7] CRM payment analysis... ');  const payCount = await collectPaymentEvidence(graph, index, members);  console.log(`${payCount} evidence edges`);  // Source 8: Manual overrides ΓÇö admin-confirmed relationships  process.stdout.write('   [8/8] Manual overrides... ');  const manualCount = applyManualOverrides(graph, index);  console.log(`${manualCount} evidence edges`);  const totalEvidence = compoundCount + fmCount + jagCount + emailCount + gcCount + edCount + payCount + manualCount;  console.log(`\n   ≡ƒôè Total evidence: ${totalEvidence} edges, ${graph.edges.size} unique pairs\n`);  // ΓöÇΓöÇΓöÇ Phase 3: Family Graph Analysis ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  console.log('≡ƒº« Phase 3: Computing family groups...\n');  const familyComponents = graph.findFamilies(FAMILY_THRESHOLD);  // Members with no edges ΓåÆ individual families  const membersWithEdges = new Set();  for (const component of familyComponents) {    for (const mid of component) membersWithEdges.add(mid);  }  const loneMembers = members.filter(m => !membersWithEdges.has(m.memberId));  // Assign family IDs  const newFamilies = new Map();      // newFamId ΓåÆ [member, ...]  const memberToNewFamily = new Map(); // memberId ΓåÆ newFamId  // Process connected components  for (const component of familyComponents) {    const memberGroup = component.map(id => index.byId.get(id)).filter(Boolean);    if (memberGroup.length === 0) continue;    // Check if all members already share the same familyId    const existingFamIds = new Set(memberGroup.map(m => m.familyId).filter(Boolean));    let famId;    if (existingFamIds.size === 1 && memberGroup.length === members.filter(m => m.familyId === [...existingFamIds][0]).length) {      // Current family is already correct ΓåÆ keep existing ID      famId = [...existingFamIds][0];    } else {      // Need new family ID      famId = generateFamilyId();    }    newFamilies.set(famId, memberGroup);    for (const m of memberGroup) {      memberToNewFamily.set(m.memberId, famId);    }  }  // Lone members ΓåÆ each gets a UNIQUE individual family  // Do NOT reuse old familyId ΓÇö old grouping was by surname which is wrong  for (const m of loneMembers) {    // Check if this member's OLD familyId is shared with other lone members    // If so, we must NOT reuse it ΓÇö that would recreate the old wrong grouping    const oldFamShared = loneMembers.filter(x => x.familyId === m.familyId).length > 1;    const famId = oldFamShared ? generateFamilyId() : (m.familyId || generateFamilyId());        // Avoid duplicate family IDs from different lone members    if (newFamilies.has(famId) && !newFamilies.get(famId).includes(m)) {      const uniqueFamId = generateFamilyId();      newFamilies.set(uniqueFamId, [m]);      memberToNewFamily.set(m.memberId, uniqueFamId);    } else {      newFamilies.set(famId, [m]);      memberToNewFamily.set(m.memberId, famId);    }  }  console.log(`   Γ£ö ${newFamilies.size} families computed:`);  const sizeDistrib = {};  for (const [, ml] of newFamilies) {    const s = ml.length;    sizeDistrib[s] = (sizeDistrib[s] || 0) + 1;  }  for (const [size, count] of Object.entries(sizeDistrib).sort((a, b) => a[0] - b[0])) {    console.log(`     ${count} families of size ${size}`);  }  // ΓöÇΓöÇΓöÇ Phase 4: Diff ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  console.log('\n≡ƒôï Phase 4: Computing changes...\n');  const diff = computeDiff(members, newFamilies, memberToNewFamily);  console.log(`   Γ£ö ${diff.changes.length} members need family reassignment`);  console.log(`   Γ£ö ${diff.unchanged.length} members already correct\n`);  // Print key changes  const problemFamilies = new Map();  for (const c of diff.changes) {    if (!problemFamilies.has(c.oldFamilyId)) problemFamilies.set(c.oldFamilyId, []);    problemFamilies.get(c.oldFamilyId).push(c);  }  const biggestProblems = [...problemFamilies.entries()]    .sort((a, b) => b[1].length - a[1].length)    .slice(0, 15);  for (const [oldFam, changeList] of biggestProblems) {    const newFams = new Set(changeList.map(c => c.newFamilyId));    console.log(`   ${oldFam} (${changeList.length} members) ΓåÆ splits into ${newFams.size} families:`);    for (const nf of newFams) {      const nfMembers = changeList.filter(c => c.newFamilyId === nf);      console.log(`     ${nf}: ${nfMembers.map(c => c.name).join(', ')}`);    }    console.log('');  }  // ΓöÇΓöÇΓöÇ Phase 5: Output ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  console.log('≡ƒÆ╛ Phase 5: Generating outputs...\n');  // 5a. JSON mapping file  const mapping = {    generatedAt: new Date().toISOString(),    totalMembers: members.length,    totalFamilies: newFamilies.size,    membersChanged: diff.changes.length,    familyThreshold: FAMILY_THRESHOLD,    evidenceEdges: graph.edges.size,    families: [...newFamilies.entries()].map(([famId, memberList]) => ({      familyId: famId,      familyType: inferFamilyType(memberList),      displayName: inferFamilyDisplayName(memberList),      memberCount: memberList.length,      members: memberList.map(m => ({        memberId: m.memberId,        firstName: m.firstName,        lastName: m.lastName,        email: m.email,        previousFamilyId: m.familyId      }))    })),    changes: diff.changes.map(c => ({      memberId: c.memberId,      name: c.name,      email: c.email,      oldFamilyId: c.oldFamilyId,      newFamilyId: c.newFamilyId,      newGroupSize: c.newGroupSize,      newGroupNames: c.newGroupNames,      evidence: graph.getEvidenceFor(c.memberId).map(e => ({        otherMemberId: e.other,        otherName: index.byId.get(e.other) ? `${index.byId.get(e.other).firstName} ${index.byId.get(e.other).lastName}` : e.other,        weight: e.weight,        sources: e.evidence.map(ev => `[${ev.source}] ${ev.detail}`)      }))    }))  };  const jsonPath = path.join(__dirname, 'family-fix-mapping.json');  fs.writeFileSync(jsonPath, JSON.stringify(mapping, null, 2));  console.log(`   Γ£ö Saved: ${jsonPath}`);  // 5b. HTML report  const html = generateReport(members, graph, newFamilies, memberToNewFamily, diff, jagRels);  const htmlPath = path.join(__dirname, 'family-fix-report.html');  fs.writeFileSync(htmlPath, html);  console.log(`   Γ£ö Saved: ${htmlPath}`);  // ΓöÇΓöÇΓöÇ Phase 6: Apply CRM Fixes ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  if (DO_FIX && diff.changes.length > 0) {    await applyFixes(members, newFamilies, memberToNewFamily);  } else if (diff.changes.length > 0) {    console.log(`\n   Γä╣  ${diff.changes.length} changes ready. Run with --fix to apply.`);  } else {    console.log('\n   Γ£à All family assignments are already correct!');  }  // ΓöÇΓöÇΓöÇ Summary ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  SUMMARY');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log(`  Members analyzed:      ${members.length}`);  console.log(`  Evidence sources:      7`);  console.log(`  Evidence edges:        ${totalEvidence} (${graph.edges.size} unique pairs)`);  console.log(`  Families (current):    ${new Set(members.map(m => m.familyId)).size}`);  console.log(`  Families (corrected):  ${newFamilies.size}`);  console.log(`  Members to reassign:   ${diff.changes.length}`);  console.log(`  Affected families:     ${problemFamilies.size}`);  console.log(`  Reports: family-fix-report.html, family-fix-mapping.json`);  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓò